//! IPC contract v1 between the window and the service.
//!
//! Commands are read-only and take no arguments from the frontend. When a
//! command that changes the system arrives (G3), it will accept only a plan id
//! and a one-time nonce issued by the service, never a path or an action.
//!
//! TypeScript bindings for every type here are generated by the test in
//! `tests/bindings.rs` into `apps/desktop/src/ipc/bindings.ts`.

use castellan_core::live::{Facts, MeasuredTarget, Overview, SweepReading};
use castellan_service::{CONTRACT_VERSION, Castellan};
use serde::Serialize;
use tauri::State;

/// Label of the only window.
pub const MAIN_WINDOW: &str = "main";
/// Event with a [`castellan_core::live::Pulse`], about once a second.
pub const EVENT_PULSE: &str = "castellan:pulse";
/// Event with a [`SweepEvent`] each time a sweep target finishes measuring.
pub const EVENT_SWEEP: &str = "castellan:sweep";

/// Commands registered in `invoke_handler`, in the same order as `build.rs`.
pub const COMMANDS: [&str; 4] = ["contract_version", "about", "overview", "facts"];

/// An error the window can show. `code` is stable; `message` is plain English.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(test, derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct IpcError {
    /// Stable code, such as `CST-E0101`.
    pub code: String,
    /// What happened and what to do.
    pub message: String,
}

impl IpcError {
    fn read(message: impl Into<String>) -> Self {
        Self {
            code: "CST-E0101".to_owned(),
            message: message.into(),
        }
    }
}

/// Who made this build, for the About screen.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(test, derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct About {
    /// Product name.
    pub name: String,
    /// Semantic version.
    pub version: String,
    /// Author credit.
    pub author: String,
    /// Source repository.
    pub repository: String,
    /// Development builds refuse real changes.
    pub dev_build: bool,
    /// Contract version the backend speaks.
    pub contract_version: u32,
}

/// One sweep target finished its read-only walk.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(test, derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct SweepEvent {
    /// Which folder.
    pub target: MeasuredTarget,
    /// What was found.
    pub reading: SweepReading,
}

/// The contract version, checked by the frontend before anything else.
#[tauri::command]
#[must_use]
pub fn contract_version() -> u32 {
    CONTRACT_VERSION
}

/// Credits and build facts.
#[tauri::command]
#[must_use]
pub fn about() -> About {
    About {
        name: "Castellan".to_owned(),
        version: env!("CARGO_PKG_VERSION").to_owned(),
        author: "Denner Parreiras".to_owned(),
        repository: "https://github.com/dennerparreiras/castellan".to_owned(),
        dev_build: cfg!(debug_assertions),
        contract_version: CONTRACT_VERSION,
    }
}

/// The overview: Keep Score, findings, persona. Read-only.
#[tauri::command]
pub async fn overview(service: State<'_, Castellan>) -> Result<Overview, IpcError> {
    let service = service.inner().clone();
    tauri::async_runtime::spawn_blocking(move || service.overview())
        .await
        .map_err(|error| IpcError::read(format!("The reading did not finish. {error}")))?
        .map_err(|error| IpcError::read(error.to_string()))
}

/// Drives, memory, uptime, processors. Read-only.
#[tauri::command]
pub async fn facts(service: State<'_, Castellan>) -> Result<Facts, IpcError> {
    let service = service.inner().clone();
    tauri::async_runtime::spawn_blocking(move || service.facts())
        .await
        .map_err(|error| IpcError::read(format!("The reading did not finish. {error}")))
}

#[cfg(test)]
mod bindings {
    //! Generates `apps/desktop/src/ipc/bindings.ts` from the Rust types.
    //!
    //! The test fails when the committed file is stale. To refresh it:
    //! `CASTELLAN_UPDATE_BINDINGS=1 cargo test -p castellan-desktop bindings`.

    use super::*;
    use castellan_core::live::{Drive, FindingView, Memory, Pulse, Room, SweepSize, VolumeReading};
    use castellan_core::{Band, DeductionLine, Pillar, PillarScore, ScoreReport, Severity};
    use ts_rs::{Config, TS};

    fn decl<T: TS>(cfg: &Config) -> String {
        format!("export {}\n", T::decl(cfg))
    }

    fn generate() -> String {
        let cfg = Config::new().with_large_int("number");
        let mut out = String::from(
            "// Generated from Rust by `apps/desktop/src-tauri/src/ipc.rs`. Do not edit.\n\
             // Refresh: CASTELLAN_UPDATE_BINDINGS=1 cargo test -p castellan-desktop bindings\n\n",
        );
        out.push_str(&format!(
            "export const CONTRACT_VERSION = {CONTRACT_VERSION};\n\
             export const EVENT_PULSE = \"{EVENT_PULSE}\";\n\
             export const EVENT_SWEEP = \"{EVENT_SWEEP}\";\n\
             export const COMMANDS = {commands} as const;\n\n",
            commands = serde_json::to_string(&COMMANDS).unwrap_or_default()
        ));
        for part in [
            decl::<Severity>(&cfg),
            decl::<Pillar>(&cfg),
            decl::<Band>(&cfg),
            decl::<DeductionLine>(&cfg),
            decl::<PillarScore>(&cfg),
            decl::<ScoreReport>(&cfg),
            decl::<Memory>(&cfg),
            decl::<Drive>(&cfg),
            decl::<Facts>(&cfg),
            decl::<Pulse>(&cfg),
            decl::<SweepSize>(&cfg),
            decl::<SweepReading>(&cfg),
            decl::<MeasuredTarget>(&cfg),
            decl::<Room>(&cfg),
            decl::<FindingView>(&cfg),
            decl::<VolumeReading>(&cfg),
            decl::<Overview>(&cfg),
            decl::<IpcError>(&cfg),
            decl::<About>(&cfg),
            decl::<SweepEvent>(&cfg),
        ] {
            out.push_str(&part);
            out.push('\n');
        }
        out
    }

    #[test]
    fn typescript_bindings_match_the_rust_types() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("src")
            .join("ipc")
            .join("bindings.ts");
        let fresh = generate();
        if std::env::var_os("CASTELLAN_UPDATE_BINDINGS").is_some() {
            std::fs::write(&path, &fresh).expect("write bindings");
            return;
        }
        let committed = std::fs::read_to_string(&path)
            .unwrap_or_default()
            .replace("\r\n", "\n");
        assert!(
            committed == fresh,
            "bindings.ts is stale. Run: CASTELLAN_UPDATE_BINDINGS=1 cargo test -p castellan-desktop bindings"
        );
    }

    #[test]
    fn build_script_and_handler_list_the_same_commands() {
        let build = include_str!("../build.rs");
        for command in COMMANDS {
            assert!(
                build.contains(&format!("\"{command}\"")),
                "build.rs misses {command}"
            );
        }
        let lib = include_str!("lib.rs");
        for command in COMMANDS {
            assert!(
                lib.contains(&format!("ipc::{command},")),
                "invoke_handler misses {command}"
            );
        }
        let capability = include_str!("../capabilities/main.json");
        for command in COMMANDS {
            let permission = format!("\"allow-{}\"", command.replace('_', "-"));
            assert!(
                capability.contains(&permission),
                "capability misses {permission}"
            );
        }
    }

    #[test]
    fn the_capability_grants_nothing_dangerous() {
        let capability = include_str!("../capabilities/main.json");
        for forbidden in [
            "shell:",
            "fs:",
            "http:",
            "process:",
            "opener:",
            "core:default",
            "core:webview",
            "core:window:allow-",
        ] {
            assert!(
                !capability.contains(forbidden),
                "capability grants {forbidden}"
            );
        }
    }

    #[test]
    fn the_window_config_is_locked_down() {
        let config = include_str!("../tauri.conf.json");
        assert!(config.contains("\"devtools\": false"));
        assert!(config.contains("\"freezePrototype\": true"));
        assert!(config.contains("\"withGlobalTauri\": false"));
        assert!(!config.contains("unsafe-eval"));
        assert!(!config.contains("dangerousDisableAssetCspModification"));
        let release_csp = config
            .split("\"csp\"")
            .nth(1)
            .and_then(|rest| rest.split("\"devCsp\"").next())
            .expect("a release csp before devCsp");
        assert!(
            !release_csp.contains("unsafe-inline"),
            "the release CSP allows inline code"
        );
        assert!(
            !release_csp.contains("http://localhost"),
            "the release CSP allows the dev server"
        );
    }
}
